import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.Cdp8-jB6.js";const u=JSON.parse('{"title":"ADR-091 — Station TLEs live in the served /data overlay, refreshed by one server-side fetcher","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-091.md","filePath":"adr/ADR-091.md"}'),r={name:"adr/ADR-091.md"};function d(n,e,i,l,c,h){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-091-—-station-tles-live-in-the-served-data-overlay-refreshed-by-one-server-side-fetcher" tabindex="-1">ADR-091 — Station TLEs live in the served /data overlay, refreshed by one server-side fetcher <a class="header-anchor" href="#adr-091-—-station-tles-live-in-the-served-data-overlay-refreshed-by-one-server-side-fetcher" aria-label="Permalink to &quot;ADR-091 — Station TLEs live in the served /data overlay, refreshed by one server-side fetcher&quot;">​</a></h1><blockquote><p>Status · Accepted · 2026-09-07 · Operator-directed (Physics Lab v0.9 · H4c · #464) · applies the launches overlay pattern (RFC-035 / ADR-065) to station element sets · supersedes the runtime browser→Celestrak fetch introduced with the AR sky (#405)</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Two code paths fetched station TLEs (ISS / Tiangong) from Celestrak, independently:</p><ol><li><strong>The AR sky</strong> (<code>/explore</code> &quot;look at the sky&quot;, #405) fetched Celestrak <strong>from the browser</strong> at runtime (<code>tle-source.ts</code>), cached in localStorage for a day, and fell back to a bundled sample.</li><li><strong>A build-time refresh</strong> (<code>scripts/fetch-station-tles.mjs</code>) existed but <strong>nothing ran it</strong> — its &quot;runs daily&quot; comment was false and the bundled set had gone ~49 days stale (found in H · #464).</li></ol><p>Meanwhile the Lab&#39;s <code>iss-pass</code> read the bundled JSON directly (baked into the app + the MCP image).</p><p>This is three sources of truth and a browser egress dependency. A stale TLE propagated weeks forward puts the ISS marker / pass in the wrong place; the browser fetch adds a CORS / uptime dependency at the moment a user opens the feature; and the MCP image only ever saw the baked copy.</p><p>The launches subsystem already solved the same shape (RFC-035): fetch server-side into the served <code>static/data</code> overlay, refresh it live on the VPS every 6h with no redeploy, and let the SPA read the same-origin file.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>One canonical file, one Celestrak fetcher, served from the /data overlay.</strong></p><ul><li>The element sets live in <strong><code>static/data/station-tles.json</code></strong> (served overlay), not in <code>src</code>.</li><li><strong><code>scripts/fetch-station-tles.mjs</code> is the only code that touches Celestrak</strong>, and it runs server-side in two places, exactly like launches: <ul><li>daily on <code>main</code> via <code>.github/workflows/refresh-station-tles.yml</code> (bot-commit, <code>chore(tle): refresh</code>, on the <code>ci-databot-*</code> concurrency group so it never cancels user CI);</li><li>every 6h on the prod VPS via <code>ops/refresh-prod-data.sh</code> (live overlay write, backup + min-bytes safety-restore, precompressed-sibling drop — no rebuild, no redeploy).</li></ul></li><li><strong>The app reads the fresh served copy at runtime</strong> through the single resolver <code>resolveStationTle</code> / <code>resolveStationTleBlock</code> (<code>tle-source.ts</code>), fetching same-origin <code>${base}/data/station-tles.json</code>, memoised per session, <strong>with no browser→Celestrak egress</strong>. Both the AR sky and the Lab&#39;s injected <code>iss-pass</code> TLE go through it.</li><li><strong>The build-baked import</strong> (<code>stations.ts</code> → <code>static/data/station-tles.json</code>) is the offline / MCP fallback. The MCP image carries the baked copy; a manually-deployed container that lags is not silently wrong because <code>iss-pass</code> discloses <code>epochAgeDays</code> vs <code>staleAfterDays</code> (H5).</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>No browser egress; one Celestrak-fetching code path; prod freshness ≤6h without a redeploy.</li><li>The AR-sky consumer is unchanged at the call site (<code>resolveStationTle</code> keeps its signature); only the source behind it changed.</li><li>Freshness is now uniform across the AR sky, the Lab, and (baked + disclosed) the MCP tool.</li><li>Trade-off: the served copy and the baked copy can diverge between deploys — intended. The app prefers the served (fresh) copy; the baked copy is the honest, age-disclosed fallback.</li></ul>',13)])])}const f=t(r,[["render",d]]);export{u as __pageData,f as default};
